export const expandedQuestions: Record<string, ExpansionQuestion[]> = Object.fromEntries(
  Object.entries(concepts).map(([topicId, topicConcepts]) => [
    topicId,
    topicConcepts.flatMap(([answer, clue, alternateClue, explanationQuestion, explanationAnswer, difficulty]) => [
      { q: clue, a: answer, difficulty, kind: "short" as const },
      { q: alternateClue, a: answer, difficulty, kind: "short" as const },
      { q: explanationQuestion, a: explanationAnswer, difficulty, kind: "explain" as const },
    ]),
  ]),
);

export const expandedOneWordQuestions: Record<string, ExpansionQuestion[]> = Object.fromEntries(
  Object.entries(concepts).map(([topicId, topicConcepts]) => [
    topicId,
    topicConcepts.flatMap(([answer, clue, alternateClue, , , difficulty]) => [
      { q: clue, a: answer, difficulty, kind: "short" as const },
      { q: alternateClue, a: answer, difficulty, kind: "short" as const },
    ]),
  ]),
);

const fullyExpandedJuniorTopics = Object.values(concepts).filter((topicConcepts) => topicConcepts.length === 14).length;
if (fullyExpandedJuniorTopics !== 17) {
  throw new Error(`Expected 17 newer junior topics with 14 expansion concepts; found ${fullyExpandedJuniorTopics}.`);
}

for (const [topicId, topicConcepts] of Object.entries(concepts)) {
  if (topicConcepts.length !== 6 && topicConcepts.length !== 14) {
    throw new Error(`${topicId} must contain either 6 or 14 expansion concepts; found ${topicConcepts.length}.`);
  }

  for (const bank of [expandedQuestions[topicId], expandedOneWordQuestions[topicId]]) {
    const uniqueQuestions = new Set(bank.map((question) => question.q.trim().toLowerCase()));
    if (uniqueQuestions.size !== bank.length) {
      throw new Error(`${topicId} contains duplicate expansion question wording.`);
    }
  }

  if (expandedOneWordQuestions[topicId].some((question) => /^(?:is|are|can|could|do|does|did|will|would|should|has|have|had)\b/i.test(question.q))) {
    throw new Error(`${topicId} contains a Yes/No One Worders prompt.`);
  }
}
